class ClaidAiAPIKeyCredential(BaseModel):
    model_config = ConfigDict(title="Claid Ai API Key", hide_input_in_errors=True,
        json_schema_extra={
            "x-credential-url": "https://claid.ai/account/api",
            "x-credential-instructions": "In your Claid account, open Overview or API keys and choose Create API key. Paste the key here without the Bearer prefix. Enable Storage permission for connection checks and the permissions needed by your image or video operations. Image and video processing uses your Claid credits. NoClick checks the key by listing your connected storages.",
        })
    credential_type: Literal["claid_ai_api_key"] = Field("claid_ai_api_key", json_schema_extra={"ui:hidden": True})
    api_key: str = Field(..., min_length=1, max_length=4096, title="API key", json_schema_extra={"ui:widget": "password"})

    @field_validator("api_key", mode="before")
    @classmethod
    def check_key(cls, value):
        value = clean_secret(value, field_name="API key")
        if not value.isascii() or any(c.isspace() for c in value):
            raise ValueError("Paste the API key without a header or whitespace")
        return value

class _Input(BaseModel):
    model_config = ConfigDict(extra="forbid", hide_input_in_errors=True)


def _json_input(value, annotation):
    try:
        if isinstance(value, str):
            try:
                raw = json.loads(value)
            except ValueError:
                raw = value  # URI alternatives accept an unquoted pasted URL.
        else:
            raw = value
        adapter = TypeAdapter(annotation)
        parsed = adapter.validate_python(raw)
        return adapter.dump_json(parsed, exclude_unset=True).decode()
    except (ValueError, TypeError):
        raise ValueError("Enter JSON matching Claid's documented field structure") from None

