def _redact(value, api_key):
    # Detailed storage reads include cloud credentials. They must never become
    # workflow outputs, and upstream errors may echo the bearer key.
    if isinstance(value, dict):
        return {key: "[redacted]" if key.lower() in {"credentials", "access_key", "secret_access_key", "private_key", "token", "api_key", "authorization"} else _redact(item, api_key) for key, item in value.items()}
    if isinstance(value, list):
        return [_redact(item, api_key) for item in value]
    if isinstance(value, str):
        for secret in ([api_key] if isinstance(api_key, str) else api_key):
            value = value.replace(secret, "[redacted]")
        return value
    return value


class ClaidAiNode(WorkflowNode):
    integration_type = "automation-claid-ai"
    scope_registry = CLAID_AI_SCOPES
    connection_evidence = ConnectionEvidence(noun="Claid connected storages", operation="list_storages")

    @classmethod
    def get_config_model(cls):
        return ClaidAiFullConfig

    async def execute(self, input_data):
        if not self.config.credentials:
            raise ValueError("Connect a Claid Ai API key")
        config = self.config.config
        credential = self.config.credentials
        method, path = ROUTES[config.operation]
        values = config.model_dump(exclude_none=True, exclude_unset=True)
        for field in ("storage_id", "task_id", "ai_edit_id", "processing_request_id", "animation_id"):
            if "{" + field + "}" in path:
                path = path.replace("{" + field + "}", str(getattr(config, field)))
        kwargs = {}
        secrets = [credential.api_key]
        if config.operation in BODY_FIELDS:
            body = {key: values[key] for key in BODY_FIELDS[config.operation] if key in values}
            for key in JSON_FIELDS[config.operation]:
                if key in body:
                    body[key] = json.loads(body[key])
            if config.operation in {"create_storage", "update_storage"}:
                cloud = body.get("parameters", {}).get("credentials", {})
                secrets.extend(value for value in cloud.values() if isinstance(value, str) and value)
            kwargs["json"] = body
        try:
            async with guarded_async_client(timeout=120, trust_env=False, follow_redirects=False) as client:
                response = await client.request(method, "https://api.claid.ai" + path,
                    headers={"Authorization": "Bearer " + credential.api_key, "Accept": "application/json"}, **kwargs)
        except httpx.RequestError:
            raise ValueError("Claid request could not be completed; inspect submitted tasks before retrying a write") from None
        if not 200 <= response.status_code < 300:
            try:
                error = response.json()
                message = error.get("error_message") if isinstance(error, dict) else None
            except ValueError:
                message = None
            return {"status": "error", "http_status": response.status_code,
                "error": _redact(message or "Claid rejected the request", secrets)}
        try:
            payload = response.json()
        except ValueError:
            raise ValueError("Claid returned an unreadable JSON response") from None
        if not isinstance(payload, dict):
            raise ValueError("Claid returned an unexpected response shape")
        if "error_code" in payload or "error_message" in payload:
            return {"status": "error", "error": _redact(payload.get("error_message", "Claid rejected the request"), secrets)}
        if config.operation in {"list_storages", "list_storage_types"} and not isinstance(payload.get("data"), list):
            raise ValueError("Claid returned an unexpected storage list")
        # Preserve task status/errors inside data; ACCEPTED is not completion.
        return {"status": "success", "http_status": response.status_code, **_redact(payload, secrets)}
